from pathlib import Path
import base64, zlib, subprocess, sys

root = Path(sys.argv[1]).resolve()
patch = zlib.decompress(base64.b64decode(""))
subprocess.run(["git", "-C", str(root), "apply", "--whitespace=nowarn", "-"], input=patch, check=True)
print("PKVault V8 alpha40 quest prototype + fangame dex interaction fix applied")
